from pathlib import Path


def replace(path, old, new, count=1):
    p=Path(path)
    s=p.read_text()
    actual=s.count(old)
    if actual < count:
        raise SystemExit(f'{path}: expected at least {count}, found {actual}: {old[:160]!r}')
    p.write_text(s.replace(old,new,count))

# 1. Complete REFERENCE / REFERENCE_ARRAY type enforcement.
old = "function validateValue(definition,value,path,issues,{required=false}={}){if(value===null){if(!definition.nullable)issues.push(issue('PROHIBITED_NULL',path,'Null is not permitted.'));return;}const t=definition.valueType;const emptyString=typeof value==='string'&&!value.trim();if(required&&emptyString)issues.push(issue('EMPTY_REQUIRED_STRING',path,'Required string is empty.'));if(typeof value==='string'&&value.trim()==='<value>')issues.push(issue('PLACEHOLDER_VALUE',path,'Prompt placeholder <value> cannot be accepted as data.'));if(t==='STRING'&&typeof value!=='string')issues.push(issue('WRONG_VALUE_TYPE',path,'Expected STRING.'));else if(t==='INTEGER'&&(!Number.isInteger(value)||!Number.isFinite(value)))issues.push(issue('WRONG_VALUE_TYPE',path,'Expected finite INTEGER.'));else if(t==='NUMBER'&&(typeof value!=='number'||!Number.isFinite(value)))issues.push(issue('WRONG_VALUE_TYPE',path,'Expected finite NUMBER.'));else if(t==='BOOLEAN'&&typeof value!=='boolean')issues.push(issue('WRONG_VALUE_TYPE',path,'Expected BOOLEAN.'));else if((t==='STRING_ARRAY'||t==='REFERENCE_ARRAY')&&!Array.isArray(value))issues.push(issue('WRONG_VALUE_TYPE',path,`Expected ${t}.`));else if(t==='STRING_ARRAY'&&Array.isArray(value)&&value.some(v=>typeof v!=='string'))issues.push(issue('WRONG_VALUE_TYPE',path,'STRING_ARRAY items must be strings.'));else if(t==='OBJECT'&&!object(value))issues.push(issue('WRONG_VALUE_TYPE',path,'Expected OBJECT.'));if(required&&Array.isArray(value)&&!value.length)issues.push(issue('EMPTY_REQUIRED_ARRAY',path,'Required array is empty.'));if(definition.enumValues?.length&&!definition.enumValues.includes(value))issues.push(issue('INVALID_ENUM_VALUE',path,`Value must be one of ${definition.enumValues.join(', ')}.`));if(typeof value==='string'&&value.length>200000)issues.push(issue('TEXT_FIELD_TOO_LARGE',path,'Text field exceeds the configured maximum length.'));if(t==='OBJECT'&&object(value)&&definition.closedProperties)for(const key of Object.keys(value))if(!definition.closedProperties.includes(key))issues.push(issue('UNKNOWN_NESTED_PROPERTY',`${path}/${pointerEscape(key)}`,`Unknown nested property ${key}.`));}"
new = "function validateValue(definition,value,path,issues,{required=false}={}){if(value===null){if(!definition.nullable)issues.push(issue('PROHIBITED_NULL',path,'Null is not permitted.'));return;}const t=definition.valueType;const emptyString=typeof value==='string'&&!value.trim();if(required&&emptyString)issues.push(issue('EMPTY_REQUIRED_STRING',path,'Required string is empty.'));if(typeof value==='string'&&value.trim()==='<value>')issues.push(issue('PLACEHOLDER_VALUE',path,'Prompt placeholder <value> cannot be accepted as data.'));if(t==='STRING'&&typeof value!=='string')issues.push(issue('WRONG_VALUE_TYPE',path,'Expected STRING.'));else if(t==='INTEGER'&&(!Number.isInteger(value)||!Number.isFinite(value)))issues.push(issue('WRONG_VALUE_TYPE',path,'Expected finite INTEGER.'));else if(t==='NUMBER'&&(typeof value!=='number'||!Number.isFinite(value)))issues.push(issue('WRONG_VALUE_TYPE',path,'Expected finite NUMBER.'));else if(t==='BOOLEAN'&&typeof value!=='boolean')issues.push(issue('WRONG_VALUE_TYPE',path,'Expected BOOLEAN.'));else if(t==='REFERENCE'&&(typeof value!=='string'||!value.trim()))issues.push(issue('WRONG_VALUE_TYPE',path,'Expected non-empty REFERENCE string.'));else if((t==='STRING_ARRAY'||t==='REFERENCE_ARRAY')&&!Array.isArray(value))issues.push(issue('WRONG_VALUE_TYPE',path,`Expected ${t}.`));else if(t==='STRING_ARRAY'&&Array.isArray(value)&&value.some(v=>typeof v!=='string'))issues.push(issue('WRONG_VALUE_TYPE',path,'STRING_ARRAY items must be strings.'));else if(t==='REFERENCE_ARRAY'&&Array.isArray(value)&&value.some(v=>typeof v!=='string'||!v.trim()))issues.push(issue('WRONG_VALUE_TYPE',path,'REFERENCE_ARRAY items must be non-empty reference strings.'));else if(t==='OBJECT'&&!object(value))issues.push(issue('WRONG_VALUE_TYPE',path,'Expected OBJECT.'));if(required&&Array.isArray(value)&&!value.length)issues.push(issue('EMPTY_REQUIRED_ARRAY',path,'Required array is empty.'));if(definition.enumValues?.length&&!definition.enumValues.includes(value))issues.push(issue('INVALID_ENUM_VALUE',path,`Value must be one of ${definition.enumValues.join(', ')}.`));if(typeof value==='string'&&value.length>200000)issues.push(issue('TEXT_FIELD_TOO_LARGE',path,'Text field exceeds the configured maximum length.'));if(t==='OBJECT'&&object(value)&&definition.closedProperties)for(const key of Object.keys(value))if(!definition.closedProperties.includes(key))issues.push(issue('UNKNOWN_NESTED_PROPERTY',`${path}/${pointerEscape(key)}`,`Unknown nested property ${key}.`));}"
