# 2. Make response types semantically exclusive and fail closed.
old = "  if(envelope.responseType==='DATA_PROPOSAL'){\n    if(safe(envelope.humanInputRequests).some(request=>request.blocking!==false))issues.push(issue('MIXED_RESPONSE_TYPE','/humanInputRequests','A DATA_PROPOSAL cannot contain blocking human-input requests.'));\n    const hasData=Object.keys(envelope.stageData||{}).length||Object.values(envelope.records||{}).some(list=>safe(list).length);\n    if(!hasData)issues.push(issue('EMPTY_DATA_PROPOSAL','/','DATA_PROPOSAL contains no stage data or records.'));\n    if(!safe(envelope.evidence).length)issues.push(issue('MISSING_PROVENANCE','/evidence','DATA_PROPOSAL requires evidence.'));\n  }\n  if(envelope.responseType==='BLOCKED'){if(Object.keys(envelope.stageData||{}).length||Object.values(envelope.records||{}).some(list=>safe(list).length)||safe(envelope.humanInputRequests).length)issues.push(issue('MIXED_RESPONSE_TYPE','/','BLOCKED must not contain stageData, records, or humanInputRequests.'));if(!safe(envelope.unresolved).length)issues.push(issue('MISSING_BLOCKER_DETAIL','/unresolved','BLOCKED requires structured unresolved detail.'));}\n  if(envelope.responseType==='EXECUTION_FAILED'){if(Object.keys(envelope.stageData||{}).length||Object.values(envelope.records||{}).some(list=>safe(list).length))issues.push(issue('MIXED_RESPONSE_TYPE','/','EXECUTION_FAILED must not contain canonical stageData or records.'));if(!safe(envelope.unresolved).length&&!safe(envelope.warnings).length)issues.push(issue('MISSING_FAILURE_DETAIL','/unresolved','EXECUTION_FAILED requires failure detail.'));}"
new = "  if(envelope.responseType==='DATA_PROPOSAL'){\n    if(safe(envelope.humanInputRequests).some(request=>request.blocking!==false))issues.push(issue('MIXED_RESPONSE_TYPE','/humanInputRequests','A DATA_PROPOSAL cannot contain blocking human-input requests.'));\n    if(safe(envelope.unresolved).some(item=>item.blocking!==false))issues.push(issue('MIXED_RESPONSE_TYPE','/unresolved','A DATA_PROPOSAL cannot contain blocking unresolved items. Use BLOCKED instead.'));\n    const hasData=Object.keys(envelope.stageData||{}).length||Object.values(envelope.records||{}).some(list=>safe(list).length);\n    if(!hasData)issues.push(issue('EMPTY_DATA_PROPOSAL','/','DATA_PROPOSAL contains no stage data or records.'));\n    if(!safe(envelope.evidence).length)issues.push(issue('MISSING_PROVENANCE','/evidence','DATA_PROPOSAL requires evidence.'));\n  }\n  if(envelope.responseType==='BLOCKED'){if(Object.keys(envelope.stageData||{}).length||Object.values(envelope.records||{}).some(list=>safe(list).length)||safe(envelope.humanInputRequests).length)issues.push(issue('MIXED_RESPONSE_TYPE','/','BLOCKED must not contain stageData, records, or humanInputRequests.'));if(!safe(envelope.unresolved).length)issues.push(issue('MISSING_BLOCKER_DETAIL','/unresolved','BLOCKED requires structured unresolved detail.'));else if(!safe(envelope.unresolved).some(item=>item.blocking!==false))issues.push(issue('MISSING_BLOCKING_UNRESOLVED','/unresolved','BLOCKED requires at least one actually blocking unresolved item.'));}\n  if(envelope.responseType==='EXECUTION_FAILED'){if(Object.keys(envelope.stageData||{}).length||Object.values(envelope.records||{}).some(list=>safe(list).length)||safe(envelope.humanInputRequests).length)issues.push(issue('MIXED_RESPONSE_TYPE','/','EXECUTION_FAILED must not contain canonical stageData, records, or humanInputRequests.'));if(!safe(envelope.unresolved).length&&!safe(envelope.warnings).length)issues.push(issue('MISSING_FAILURE_DETAIL','/unresolved','EXECUTION_FAILED requires failure detail.'));}"
